    <style>
      /* ── Reset & base ──────────────────────────────── */
      *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

      :root {
        --bg:           #0f1117;
        --surface:      #1a1d27;
        --surface-alt:  #22263a;
        --border:       #2e3350;
        --border-focus: #6c8bef;
