        --text-muted:   #8b90a8;
        --accent:       #6c8bef;
        --accent-hover: #8ba4f5;
        --error:        #ff6b6b;
        --error-bg:     #2a1a1a;
        --success:      #4caf82;
        --required:     #ff6b6b;
      }

