      .skip-link {
        position: absolute;
        top: -100%;
        left: 1rem;
        background: var(--accent);
        color: #fff;
        padding: 0.5rem 1rem;
        border-radius: 0 0 6px 6px;
        font-weight: 600;
        text-decoration: none;
        z-index: 9999;
        transition: top 0.1s;
      }
      .skip-link:focus { top: 0; }

