        background: var(--surface);
        border-bottom: 1px solid var(--border);
        padding: 1rem 2rem;
      }
      header .logo {
        font-size: 1.1rem;
        font-weight: 700;
        color: var(--accent);
        letter-spacing: 0.04em;
        text-decoration: none;
      }

      main {
        flex: 1;
        display: flex;
        justify-content: center;
        align-items: flex-start;
        padding: 3rem 1rem 4rem;
      }

      .card {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 2.5rem 2rem;
        width: 100%;
        max-width: 520px;
      }

      /* ── Headings ──────────────────────────────────── */
      h1 {
        font-size: 1.6rem;
        font-weight: 700;
        margin-bottom: 0.4rem;
        color: var(--text);
      }
      .card-subtitle {
        color: var(--text-muted);
        font-size: 0.93rem;
        margin-bottom: 2rem;
      }

      /* ── Required legend ───────────────────────────── */
      .required-legend {
        font-size: 0.82rem;
        color: var(--text-muted);
        margin-bottom: 1.5rem;
      }
      .required-legend .marker {
        color: var(--required);
        font-weight: 700;
        margin-right: 0.2rem;
      }

      /* ── Form field wrapper ────────────────────────── */
      .form-field {
        display: flex;
        flex-direction: column;
        gap: 0.35rem;
        margin-bottom: 1.4rem;
      }

      /* ── Labels ────────────────────────────────────── */
      label {
        font-size: 0.9rem;
        font-weight: 600;
        color: var(--text);
      }
      label .required-mark {
        color: var(--required);
        margin-left: 0.2rem;
        font-weight: 700;
      }
      label .optional-tag {
        color: var(--text-muted);
        font-size: 0.78rem;
        font-weight: 400;
        margin-left: 0.35rem;
      }

      /* ── Inputs ────────────────────────────────────── */
      input {
        background: var(--surface-alt);
        border: 1.5px solid var(--border);
        border-radius: 7px;
        color: var(--text);
        font-size: 0.95rem;
        padding: 0.62rem 0.85rem;
        width: 100%;
        transition: border-color 0.15s, box-shadow 0.15s;
        outline: none;
      }
      input::placeholder { color: var(--text-muted); }
      input:focus {
        border-color: var(--border-focus);
        box-shadow: 0 0 0 3px rgba(108, 139, 239, 0.25);
      }
      input[aria-invalid="true"] {
        border-color: var(--error);
        background: var(--error-bg);
      }
      input[aria-invalid="true"]:focus {
        box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.25);
      }

      /* ── Helper text ───────────────────────────────── */
      .help-text {
        font-size: 0.8rem;
        color: var(--text-muted);
        line-height: 1.4;
      }

      /* ── Inline error messages ─────────────────────── */
      .error-message {
        display: none;
        font-size: 0.82rem;
        color: var(--error);
        line-height: 1.4;
      }
      .error-message.visible { display: block; }

      /* ── Submit button ─────────────────────────────── */
      .btn-submit {
        width: 100%;
        margin-top: 0.6rem;
        padding: 0.78rem 1.2rem;
        background: var(--accent);
        color: #fff;
        border: none;
        border-radius: 8px;
        font-size: 1rem;
        font-weight: 600;
        cursor: pointer;
        transition: background 0.15s, box-shadow 0.15s;
        outline: none;
      }
      .btn-submit:hover { background: var(--accent-hover); }
      .btn-submit:focus-visible {
        box-shadow: 0 0 0 3px rgba(108, 139, 239, 0.45);
      }

      /* ── Status message (live region) ──────────────── */
      #form-status {
        margin-top: 1.2rem;
        font-size: 0.9rem;
        border-radius: 7px;
        padding: 0.75rem 1rem;
        display: none;
      }
      #form-status.success {
        display: block;
        background: rgba(76, 175, 130, 0.12);
        border: 1px solid var(--success);
        color: var(--success);
      }
      #form-status.error {
        display: block;
        background: var(--error-bg);
        border: 1px solid var(--error);
        color: var(--error);
      }

      /* ── Footer ────────────────────────────────────── */
      footer {
        text-align: center;
        padding: 1.2rem;
        font-size: 0.8rem;
        color: var(--text-muted);
        border-top: 1px solid var(--border);
      }

