    <title>Support – Contact Us</title>
    <style>
      /* ── Reset & base ──────────────────────────────── */
      *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

      :root {
        --bg:           #0f1117;
        --surface:      #1a1d27;
        --surface-alt:  #22263a;
        --border:       #2e3350;
        --border-focus: #6c8bef;
        --text:         #e4e6f0;
        --text-muted:   #8b90a8;
        --accent:       #6c8bef;
        --accent-hover: #8ba4f5;
        --btn-bg:       #3d5dbf;
        --btn-hover:    #4a6bcc;
        --error:        #ff6b6b;
        --error-bg:     #2a1a1a;
        --success:      #4caf82;
        --required:     #ff6b6b;
      }

      html { font-size: 16px; }

      body {
        background: var(--bg);
        color: var(--text);
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
                     Helvetica, Arial, sans-serif;
        line-height: 1.6;
        min-height: 100vh;
        display: flex;
        flex-direction: column;
      }

      /* ── Skip link ─────────────────────────────────── */
      .skip-link {
        position: absolute;
        top: -100%;
        left: 1rem;
        background: var(--accent);
        color: #fff;
        padding: 0.5rem 1rem;
        border-radius: 0 0 6px 6px;
        font-weight: 600;
        text-decoration: none;
        z-index: 9999;
        transition: top 0.1s;
      }
      .skip-link:focus { top: 0; }

      /* ── Layout ────────────────────────────────────── */
      header {
        background: var(--surface);
        border-bottom: 1px solid var(--border);
        padding: 1rem 2rem;
      }
      header .logo {
        font-size: 1.1rem;
        font-weight: 700;
        color: var(--accent);
        letter-spacing: 0.04em;
        text-decoration: none;
      }

      main {
        flex: 1;
        display: flex;
        justify-content: center;
        align-items: flex-start;
        padding: 3rem 1rem 4rem;
      }

      .card {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 12px;
        padding: 2.5rem 2rem;
        width: 100%;
        max-width: 520px;
      }

      /* ── Headings ──────────────────────────────────── */
      h1 {
        font-size: 1.6rem;
        font-weight: 700;
        margin-bottom: 0.4rem;
        color: var(--text);
      }
      .card-subtitle {
        color: var(--text-muted);
        font-size: 0.93rem;
        margin-bottom: 2rem;
      }

      /* ── Required legend ───────────────────────────── */
      .required-legend {
        font-size: 0.82rem;
        color: var(--text-muted);
        margin-bottom: 1.5rem;
      }
      .required-legend .marker {
        color: var(--required);
        font-weight: 700;
        margin-right: 0.2rem;
      }

      /* ── Form field wrapper ────────────────────────── */
      .form-field {
        display: flex;
        flex-direction: column;
        gap: 0.35rem;
        margin-bottom: 1.4rem;
      }

      /* ── Labels ────────────────────────────────────── */
      label {
        font-size: 0.9rem;
        font-weight: 600;
        color: var(--text);
      }
      label .required-mark {
        color: var(--required);
        margin-left: 0.2rem;
        font-weight: 700;
      }
      label .optional-tag {
        color: var(--text-muted);
        font-size: 0.78rem;
        font-weight: 400;
        margin-left: 0.35rem;
      }

      /* ── Inputs ────────────────────────────────────── */
      input {
        background: var(--surface-alt);
        border: 1.5px solid var(--border);
        border-radius: 7px;
        color: var(--text);
        font-size: 0.95rem;
        padding: 0.62rem 0.85rem;
        width: 100%;
        transition: border-color 0.15s, box-shadow 0.15s;
        outline: none;
      }
      input::placeholder { color: var(--text-muted); }
      input:focus {
        border-color: var(--border-focus);
        box-shadow: 0 0 0 3px rgba(108, 139, 239, 0.25);
      }
      input[aria-invalid="true"] {
        border-color: var(--error);
        background: var(--error-bg);
      }
      input[aria-invalid="true"]:focus {
        box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.25);
      }

      /* ── Helper text ───────────────────────────────── */
      .help-text {
        font-size: 0.8rem;
        color: var(--text-muted);
        line-height: 1.4;
      }

      /* ── Inline error messages ─────────────────────── */
      .error-message {
        display: none;
        font-size: 0.82rem;
        color: var(--error);
        line-height: 1.4;
      }
      .error-message.visible { display: block; }

      /* ── Submit button ─────────────────────────────── */
      .btn-submit {
        width: 100%;
        margin-top: 0.6rem;
        padding: 0.78rem 1.2rem;
        background: var(--btn-bg);
        color: #fff;
        border: none;
        border-radius: 8px;
        font-size: 1rem;
        font-weight: 600;
        cursor: pointer;
        transition: background 0.15s, box-shadow 0.15s;
        outline: none;
      }
      .btn-submit:hover { background: var(--accent-hover); }
      .btn-submit:focus-visible {
        box-shadow: 0 0 0 3px rgba(108, 139, 239, 0.45);
      }

      /* ── Status message (live region) ──────────────── */
      #form-status {
        margin-top: 1.2rem;
        font-size: 0.9rem;
        border-radius: 7px;
        padding: 0.75rem 1rem;
        display: none;
      }
      #form-status.success {
        display: block;
        background: rgba(76, 175, 130, 0.12);
        border: 1px solid var(--success);
        color: var(--success);
      }
      #form-status.error {
        display: block;
        background: var(--error-bg);
        border: 1px solid var(--error);
        color: var(--error);
      }

      /* ── Footer ────────────────────────────────────── */
      footer {
        text-align: center;
        padding: 1.2rem;
        font-size: 0.8rem;
        color: var(--text-muted);
        border-top: 1px solid var(--border);
      }

      /* ── Forced colors (high contrast mode) ────────── */
      @media (forced-colors: active) {
        input { border: 2px solid ButtonText; }
        input:focus { outline: 3px solid Highlight; }
        .btn-submit { border: 2px solid ButtonText; }
      }

      /* ── Reduced motion ────────────────────────────── */
      @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after { transition: none !important; }
      }

      /* ── Reflow / narrow viewport ──────────────────── */
      @media (max-width: 400px) {
        .card { padding: 1.5rem 1rem; }
        h1 { font-size: 1.3rem; }
      }
    </style>
  </head>
  <body>
    <a href="#main-content" class="skip-link">Skip to main content</a>

    <header>
      <a href="/" class="logo" aria-label="Acme Support – home">Acme Support</a>
    </header>

    <main id="main-content" tabindex="-1">
      <div class="card">
        <h1>Contact Us</h1>
        <p class="card-subtitle">Our team will get back to you within one business day.</p>

        <p class="required-legend">
          <span class="marker" aria-hidden="true">*</span>
          Required fields
        </p>

        <form id="contact-form" novalidate aria-label="Support contact form">

          <!-- Full Name -->
          <div class="form-field">
            <label for="full-name">
              Full name
              <span class="required-mark" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              required
              autocomplete="name"
              aria-required="true"
              aria-describedby="full-name-error"
              placeholder="Jane Smith"
            />
            <span id="full-name-error" class="error-message" role="alert"></span>
          </div>

          <!-- Email Address -->
          <div class="form-field">
            <label for="email">
              Email address
              <span class="required-mark" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              required
              autocomplete="email"
              aria-required="true"
              aria-describedby="email-error"
              placeholder="jane@example.com"
            />
            <span id="email-error" class="error-message" role="alert"></span>
          </div>

          <!-- Phone Number (optional) -->
          <div class="form-field">
            <label for="phone">
              Phone number
              <span class="optional-tag">(optional)</span>
            </label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
              placeholder="+1 555 000 0000"
            />
            <span id="phone-help" class="help-text">
              Enter your number in international format, e.g.&nbsp;<strong>+1 555 000 0000</strong>. Include the country code.
            </span>
            <span id="phone-error" class="error-message" role="alert"></span>
          </div>

          <button type="submit" class="btn-submit">Send message</button>

          <!-- Live region for submission status -->
          <div id="form-status" aria-live="polite" aria-atomic="true"></div>
        </form>
      </div>
    </main>

    <footer>
      <p>&copy; 2026 Acme Inc. All rights reserved.</p>
    </footer>

    <script>
      (function () {
        "use strict";

        // ── Field descriptors ───────────────────────────────────────────────
        const fields = [
          {
            id: "full-name",
            errorId: "full-name-error",
            required: true,
            validate(value) {
              if (!value.trim()) return "Error: Full name is required.";
              if (value.trim().length < 2) return "Error: Enter your full name (at least 2 characters).";
              return null;
            },
          },
          {
            id: "email",
            errorId: "email-error",
            required: true,
            validate(value) {
              if (!value.trim()) return "Error: Email address is required.";
              // RFC-friendly basic check
              if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
                return "Error: Enter a valid email address, e.g. name@example.com.";
              return null;
            },
          },
          {
            id: "phone",
            errorId: "phone-error",
            required: false,
            validate(value) {
              if (!value.trim()) return null; // optional
              // Allow digits, spaces, dashes, parens, leading +
              if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
                return "Error: Enter a valid phone number in international format, e.g. +1 555 000 0000.";
              return null;
            },
          },
        ];

        // ── Helpers ─────────────────────────────────────────────────────────
        function getEl(id) { return document.getElementById(id); }

        function setError(field, message) {
          const input = getEl(field.id);
          const errorEl = getEl(field.errorId);
          if (message) {
            input.setAttribute("aria-invalid", "true");
            errorEl.textContent = message;
            errorEl.classList.add("visible");
          } else {
            input.removeAttribute("aria-invalid");
            errorEl.textContent = "";
            errorEl.classList.remove("visible");
          }
        }

        // ── Inline validation on blur ────────────────────────────────────────
        fields.forEach((field) => {
          const input = getEl(field.id);
          input.addEventListener("blur", () => {
            const err = field.validate(input.value);
            setError(field, err);
          });
          // Clear error as user types once a field has been touched
          input.addEventListener("input", () => {
            if (input.hasAttribute("aria-invalid")) {
              const err = field.validate(input.value);
              setError(field, err);
            }
          });
        });

        // ── Submit handler ───────────────────────────────────────────────────
        const form = getEl("contact-form");
        const status = getEl("form-status");

        form.addEventListener("submit", (e) => {
          e.preventDefault();

          // Validate all fields
          const errors = fields.map((field) => ({
            field,
            error: field.validate(getEl(field.id).value),
          }));

          const firstError = errors.find((r) => r.error !== null);

          // Apply error states
          errors.forEach(({ field, error }) => setError(field, error));

          if (firstError) {
            // Focus first invalid control
            getEl(firstError.field.id).focus();

            status.className = "error";
            status.textContent =
              "Please fix the errors above before sending your message.";
            return;
          }

          // Success (demo only — no real network request)
          status.className = "success";
          status.textContent =
            "✓ Message sent! We'll be in touch within one business day.";

          form.reset();
          fields.forEach((field) => setError(field, null));
        });
      })();
    </script>
  </body>
</html>
